CREATE TABLE public.day_closes(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,day date NOT NULL,mood text NOT NULL CHECK(mood IN('strong','proud','okay','tired','low')),tomorrow text NOT NULL DEFAULT '' CHECK(char_length(tomorrow)<=120),created_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,day));
GRANT SELECT ON public.day_closes TO authenticated; GRANT ALL ON public.day_closes TO service_role; ALTER TABLE public.day_closes ENABLE ROW LEVEL SECURITY; CREATE POLICY own_closes ON public.day_closes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.capsules(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,season_id uuid NOT NULL REFERENCES public.seasons(id),body text NOT NULL DEFAULT '' CHECK(char_length(body)<=1000),audio_url text,sealed_at timestamptz NOT NULL DEFAULT now(),opens_on date NOT NULL,is_demo boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,season_id));
GRANT ALL ON public.capsules TO service_role; ALTER TABLE public.capsules ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.moments_seen(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,key text NOT NULL,season_id uuid NOT NULL REFERENCES public.seasons(id),created_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,key,season_id));
GRANT SELECT ON public.moments_seen TO authenticated; GRANT ALL ON public.moments_seen TO service_role; ALTER TABLE public.moments_seen ENABLE ROW LEVEL SECURITY; CREATE POLICY own_moments ON public.moments_seen FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.moment_reminders(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,day date NOT NULL,due_at timestamptz NOT NULL,read_at timestamptz,is_demo boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,day));
GRANT SELECT ON public.moment_reminders TO authenticated; GRANT ALL ON public.moment_reminders TO service_role; ALTER TABLE public.moment_reminders ENABLE ROW LEVEL SECURITY; CREATE POLICY own_moment_reminders ON public.moment_reminders FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.capsules(user_id,season_id,body,opens_on,is_demo) SELECT c.user_id,c.season_id,left(c.note,1000),s.ends_on,c.is_demo FROM public.time_capsules c JOIN public.seasons s ON s.id=c.season_id WHERE length(trim(c.note))>0 ON CONFLICT DO NOTHING;
COMMENT ON TABLE public.time_capsules IS 'DEPRECATED: replaced by time-locked capsules'; REVOKE ALL ON public.time_capsules FROM authenticated,anon;
CREATE FUNCTION public.capsule_read(_season_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.capsules; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM season_entries WHERE user_id=auth.uid() AND season_id=_season_id) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO c FROM capsules WHERE user_id=auth.uid() AND season_id=_season_id; IF NOT FOUND THEN RETURN jsonb_build_object('sealed',false); END IF; IF _local_today(auth.uid())<c.opens_on THEN RETURN jsonb_build_object('sealed',true,'locked',true,'opens_on',c.opens_on); END IF; RETURN jsonb_build_object('sealed',true,'locked',false,'opens_on',c.opens_on,'body',c.body,'audio_url',c.audio_url); END $$;
CREATE FUNCTION public.seal_capsule(_season_id uuid,_body text DEFAULT '',_audio_path text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.seasons; BEGIN SELECT s0.* INTO s FROM seasons s0 JOIN season_entries e ON e.season_id=s0.id WHERE s0.id=_season_id AND e.user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'forbidden'; END IF; IF _local_today(auth.uid())>=s.ends_on THEN RAISE EXCEPTION 'season_ended'; END IF; IF char_length(coalesce(_body,''))>1000 OR (length(trim(coalesce(_body,'')))=0 AND _audio_path IS NULL) THEN RAISE EXCEPTION 'invalid_note'; END IF; IF _audio_path IS NOT NULL AND (split_part(_audio_path,'/',1)<>auth.uid()::text OR split_part(_audio_path,'/',2)<>_season_id::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='capsule-audio' AND name=_audio_path)) THEN RAISE EXCEPTION 'invalid_audio'; END IF; INSERT INTO capsules(user_id,season_id,body,audio_url,opens_on,is_demo) SELECT auth.uid(),s.id,coalesce(_body,''),_audio_path,s.ends_on,is_demo FROM profiles WHERE id=auth.uid(); END $$;
CREATE FUNCTION public.close_my_day(_mood text,_tomorrow text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'forbidden'; END IF; INSERT INTO day_closes(user_id,day,mood,tomorrow,is_demo) SELECT id,_local_today(id),_mood,coalesce(_tomorrow,''),is_demo FROM profiles WHERE id=auth.uid() AND account_status='active' ON CONFLICT(user_id,day) DO UPDATE SET mood=excluded.mood,tomorrow=excluded.tomorrow; END $$;
CREATE FUNCTION public.signature_overview(_season_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid();d date;tz text;res jsonb;s public.seasons;prev int;miss int; BEGIN IF u IS NULL OR NOT EXISTS(SELECT 1 FROM season_entries WHERE user_id=u AND season_id=_season_id) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO s FROM seasons WHERE id=_season_id; SELECT timezone INTO tz FROM profiles WHERE id=u;d:=_local_today(u);SELECT coalesce(streak,0) INTO prev FROM daily_scores WHERE user_id=u AND season_id=s.id AND day=d-1;SELECT greatest(0,d-coalesce(max(day),s.starts_on)-1)::int INTO miss FROM daily_scores WHERE user_id=u AND season_id=s.id AND completion>=0.6 AND day<d;
SELECT jsonb_build_object('today',d,'hour',extract(hour FROM _account_now(u) AT TIME ZONE tz),'day',greatest(1,d-s.starts_on+1),'length',s.ends_on-s.starts_on+1,'closes',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY day),'[]') FROM day_closes c WHERE user_id=u AND day BETWEEN s.starts_on AND s.ends_on),'closed',EXISTS(SELECT 1 FROM day_closes WHERE user_id=u AND day=d),'tomorrow',(SELECT tomorrow FROM day_closes WHERE user_id=u AND day=d-1),'capsule',capsule_read(s.id),'seen',(SELECT coalesce(jsonb_agg(key),'[]') FROM moments_seen WHERE user_id=u AND season_id=s.id),'previous_streak',coalesce(prev,0),'missed',coalesce(miss,0),'days_done',(SELECT count(*) FROM daily_scores WHERE user_id=u AND season_id=s.id AND completion>=0.6),'trophy',EXISTS(SELECT 1 FROM season_trophies WHERE user_id=u AND season_id=s.id),'reminder_due',EXISTS(SELECT 1 FROM moment_reminders WHERE user_id=u AND day=d AND read_at IS NULL AND due_at<=_account_now(u)),'crew',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'handle',p.handle,'name',p.display_name,'avatar_url',p.avatar_url,'day',greatest(1,least(s.ends_on-s.starts_on+1,coalesce((SELECT max(day) FROM checkins WHERE user_id=p.id AND value>0),s.starts_on)-s.starts_on+1)))),'[]') FROM profiles p WHERE p.id<>u AND p.id IN(SELECT m.user_id FROM crew_members m JOIN crews c ON c.id=m.crew_id WHERE c.season_id=s.id AND NOT c.archived AND m.crew_id IN(SELECT crew_id FROM crew_members WHERE user_id=u)))) INTO res; RETURN res; END $$;
CREATE FUNCTION public.claim_moment(_season_id uuid,_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid();d date;h int;ok boolean:=false;n int;st int;BEGIN IF u IS NULL OR NOT EXISTS(SELECT 1 FROM season_entries WHERE user_id=u AND season_id=_season_id) THEN RAISE EXCEPTION 'forbidden'; END IF;d:=_local_today(u);SELECT extract(hour FROM _account_now(u) AT TIME ZONE timezone)::int INTO h FROM profiles WHERE id=u;
IF _key='first' THEN ok:=EXISTS(SELECT 1 FROM checkins c JOIN user_habits uh ON uh.id=c.user_habit_id WHERE c.user_id=u AND uh.season_id=_season_id AND _habit_completion(uh.kind,uh.target,c.value,c.detail)>=1);
ELSIF _key='comeback' THEN ok:=EXISTS(SELECT 1 FROM daily_scores WHERE user_id=u AND season_id=_season_id AND day=d AND comeback);
ELSIF _key='trophy' THEN ok:=d>=(SELECT ends_on FROM seasons WHERE id=_season_id) AND EXISTS(SELECT 1 FROM season_trophies WHERE user_id=u AND season_id=_season_id);
ELSIF _key='finish' THEN ok:=d BETWEEN (SELECT ends_on-3 FROM seasons WHERE id=_season_id) AND (SELECT ends_on FROM seasons WHERE id=_season_id) AND NOT EXISTS(SELECT 1 FROM season_trophies WHERE user_id=u AND season_id=_season_id);
ELSIF _key='risk:'||d::text THEN SELECT coalesce(streak,0) INTO st FROM daily_scores WHERE user_id=u AND season_id=_season_id AND day=d-1;ok:=h>=21 AND coalesce(st,0)>0 AND coalesce((SELECT completion FROM daily_scores WHERE user_id=u AND season_id=_season_id AND day=d),0)<0.6 AND d<=(SELECT ends_on FROM seasons WHERE id=_season_id);
ELSIF _key='lights:'||d::text THEN ok:=h>=21 AND NOT EXISTS(SELECT 1 FROM day_closes WHERE user_id=u AND day=d);
ELSIF _key LIKE 'badge:%' THEN ok:=EXISTS(SELECT 1 FROM badges WHERE user_id=u AND season_id=_season_id AND key=substring(_key FROM 7)); ELSE RAISE EXCEPTION 'invalid_moment'; END IF;
IF NOT ok THEN RETURN false; END IF; INSERT INTO moments_seen(user_id,key,season_id,is_demo) SELECT u,_key,_season_id,is_demo FROM profiles WHERE id=u ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n=1; END $$;
CREATE FUNCTION public.remind_moment(_season_id uuid,_read boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d date;tz text; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM season_entries WHERE user_id=auth.uid() AND season_id=_season_id) THEN RAISE EXCEPTION 'forbidden'; END IF; d:=_local_today(auth.uid());SELECT timezone INTO tz FROM profiles WHERE id=auth.uid();IF _read THEN UPDATE moment_reminders SET read_at=now() WHERE user_id=auth.uid() AND day=d; ELSE IF (_account_now(auth.uid()) AT TIME ZONE tz)::time>=time '23:00' THEN RAISE EXCEPTION 'reminder_passed'; END IF; INSERT INTO moment_reminders(user_id,day,due_at,is_demo) SELECT id,d,(d+time '23:00') AT TIME ZONE tz,is_demo FROM profiles WHERE id=auth.uid() ON CONFLICT DO NOTHING; END IF;END $$;
REVOKE ALL ON FUNCTION public.capsule_read(uuid),public.seal_capsule(uuid,text,text),public.close_my_day(text,text),public.signature_overview(uuid),public.claim_moment(uuid,text),public.remind_moment(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.capsule_read(uuid),public.seal_capsule(uuid,text,text),public.close_my_day(text,text),public.signature_overview(uuid),public.claim_moment(uuid,text),public.remind_moment(uuid,boolean) TO authenticated,service_role;
CREATE POLICY capsule_audio_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='capsule-audio' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM season_entries WHERE user_id=auth.uid() AND season_id::text=(storage.foldername(name))[2]) AND NOT EXISTS(SELECT 1 FROM capsules WHERE user_id=auth.uid() AND season_id::text=(storage.foldername(name))[2]));
CREATE POLICY capsule_audio_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='capsule-audio' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM capsules WHERE user_id=auth.uid() AND audio_url=name AND _local_today(auth.uid())>=opens_on));
CREATE POLICY capsule_audio_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='capsule-audio' AND (storage.foldername(name))[1]=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM capsules WHERE audio_url=name));
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.wrapped_summary(uuid)'::regprocedure) INTO f; f:=replace(f,'(SELECT note FROM public.time_capsules WHERE user_id=uid AND season_id=_season_id)','(public.capsule_read(_season_id)->>''body'')');EXECUTE f;END $$;